#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int N, K, U;
    if (scanf("%d %d %d", &N, &K, &U) != 3) return 0;

    /* listas de cartelas por número sorteável */
    int cnt = (int *)calloc(U + 1, sizeof(int));
    int **cards_of = (int **)malloc((U + 1) * sizeof(int *));
    for (int i = 0; i <= U; i++) {
        cards_of[i] = (int *)malloc(N * sizeof(int));
    }

    int *remaining = (int *)malloc(N * sizeof(int));
    int *finish_step = (int *)malloc(N * sizeof(int));

    for (int c = 0; c < N; c++) {
        remaining[c] = K;
        finish_step[c] = -1;
        for (int j = 0; j < K; j++) {
            int x;
            scanf("%d", &x);
            cards_of[x][cnt[x]++] = c;
        }
    }

    int finished_count = 0;
    for (int step = 1; step <= U; step++) {
        int x;
        scanf("%d", &x);
        if (finished_count == N) continue; /* ainda precisa ler o resto da entrada */
        int m = cnt[x];
        int *list = cards_of[x];
        for (int i = 0; i < m; i++) {
            int c = list[i];
            if (finish_step[c] == -1) {
                if (--remaining[c] == 0) {
                    finish_step[c] = step;
                    finished_count++;
                }
            }
        }
        if (finished_count == N) {
            /* podemos parar de processar, mas continuar lendo a entrada é seguro */
        }
    }

    int best = -1;
    for (int c = 0; c < N; c++) {
        if (finish_step[c] != -1 && (best == -1 || finish_step[c] < best))
            best = finish_step[c];
    }

    int first = 1;
    for (int c = 0; c < N; c++) {
        if (finish_step[c] == best) {
            if (!first) printf(" ");
            printf("%d", c + 1);
            first = 0;
        }
    }
    printf("\n");

    return 0;
}
